import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

class AppCustomIcons {
  static final Uint8List personaBytes = base64Decode('');
  static final Uint8List cdBytes = base64Decode('');
  static final Uint8List fuegoBytes = base64Decode('');
  static final Uint8List libreriaBytes = base64Decode('');
  static final Uint8List epBytes = base64Decode('');
  static final Uint8List notaBytes = base64Decode('');
  static final Uint8List grupoBytes = base64Decode('');

  static Widget _img(Uint8List bytes, {double size = 16, Color? color}) {
    return Image.memory(
      bytes,
      width: size,
      height: size,
      color: color,
      fit: BoxFit.contain,
    );
  }

  static Widget persona({double size = 16, Color? color}) => _img(personaBytes, size: size, color: color);
  static Widget cd({double size = 16, Color? color}) => _img(cdBytes, size: size, color: color);
  static Widget fuego({double size = 18, Color? color}) => _img(fuegoBytes, size: size, color: color);
  static Widget libreria({double size = 16, Color? color}) => _img(libreriaBytes, size: size, color: color);
  static Widget ep({double size = 16, Color? color}) => _img(epBytes, size: size, color: color);
  static Widget nota({double size = 16, Color? color}) => _img(notaBytes, size: size, color: color);
  static Widget grupo({double size = 16, Color? color}) => _img(grupoBytes, size: size, color: color);
}
